"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[4825],{2555(t,e,a){a.r(e),a.d(e,{assets:()=>c,contentTitle:()=>l,default:()=>u,frontMatter:()=>d,metadata:()=>n,toc:()=>p});const n=JSON.parse('{"id":"content-map","title":"Reading Guide and Concept Map","description":"This page is the book-level map. It explains the main spine of the book, where each concept is introduced, and where the same idea is revisited from an implementation, architecture, enterprise, or reference angle. Rep...","source":"@site/docs/content-map.mdx","sourceDirName":".","slug":"/content-map","permalink":"/tutorials/content-map","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"frontMatter":{"title":"Reading Guide and Concept Map","slug":"/content-map","description":"This page is the book-level map. It explains the main spine of the book, where each concept is introduced, and where the same idea is revisited from an implementation, architecture, enterprise, or reference angle. Rep...","sidebar_label":"Reading guide and concept map","pagination_label":"Reading guide and concept map","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"Book home","permalink":"/tutorials/"},"next":{"title":"Part overview","permalink":"/tutorials/part1-enterprise-ai-delivery/overview"}}');var r=a(4848),i=a(8453),o=a(8172);const s=JSON.parse('{"sourcePath":"content-map.html","route":"/content-map","kind":"map","partId":"book","partLabel":"Enterprise AI, Agents & Applied ML","accent":"blue","heading":"Reading Guide and Concept Map","title":"Reading Guide and Concept Map","description":"This page is the book-level map. It explains the main spine of the book, where each concept is introduced, and where the same idea is revisited from an implementation, architecture, enterprise, or reference angle. Rep...","readingMinutes":9,"bodyClass":"","normalizeMath":false,"toc":[{"id":"book-spine","label":"Book Spine"},{"id":"concept-map","label":"Concept Map"},{"id":"cross-referenced-concept-clusters","label":"Cross-Referenced Concept Clusters"},{"id":"page-by-page-map","label":"Page-by-Page Map"}],"html":"<p>This page is the book-level map. It explains the main spine of the book,\\nwhere each concept is introduced, and where the same idea is revisited from an\\nimplementation, architecture, enterprise, or reference angle. Repetition is\\nintentional when it helps a reader move from first intuition to production\\npractice.</p>\\n\\n<div class=\\"tr-note\\">\\n  <strong>How to use this map</strong>\\n  For each major concept, start with the primary chapter, then follow the\\n  related chapters when you want a second angle: a beginner introduction,\\n  an applied implementation, an enterprise design pattern, or a reference\\n  edition.\\n</div>\\n\\n<h2 id=\\"book-spine\\">Book Spine</h2>\\n<table>\\n  <thead>\\n    <tr>\\n      <th>Part</th>\\n      <th>Primary purpose</th>\\n      <th>How to read it</th>\\n    </tr>\\n  </thead>\\n  <tbody>\\n    <tr>\\n      <td><a href=\\"/tutorials/part1-enterprise-ai-delivery/overview\\">Part I</a></td>\\n      <td>Enterprise AI delivery lifecycle: intake, kickoff, HLD, architecture review, LLD, sprint planning, provisioning, and scale.</td>\\n      <td>Read as a process story. Repeated roles, artifacts, and gates are intentional lifecycle continuity.</td>\\n    </tr>\\n    <tr>\\n      <td><a href=\\"/tutorials/part2-backend-platform-security/overview\\">Part II</a></td>\\n      <td>Backend runtime, HTTP/FastAPI mechanics, Pydantic data contracts, authentication, identity, tenancy, workload identity, external integrations, and governance.</td>\\n      <td>Read in four blocks: runtime basics, Pydantic data boundaries, auth identity, then tenancy/IAM/GCP implementation.</td>\\n    </tr>\\n    <tr>\\n      <td><a href=\\"/tutorials/part3-agent-protocols/overview\\">Part III</a></td>\\n      <td>Agent protocol integration: MCP fundamentals, remote/auth/enterprise patterns, 2025-to-2026 evolution, A2A 1.0, JS/TS, and LangChain/LangGraph/Flowise.</td>\\n      <td>Read the MCP chapters together, then A2A as the separate agent-to-agent delegation protocol.</td>\\n    </tr>\\n    <tr>\\n      <td><a href=\\"/tutorials/part4-ml-foundations/overview\\">Part IV</a></td>\\n      <td>Classical ML foundations: PyTorch, geometry, regression, classification, trees, bagging, boosting, and XGBoost.</td>\\n      <td>Read before Part V. Regression and classification share the same training workflow but differ in target, output, and loss.</td>\\n    </tr>\\n    <tr>\\n      <td><a href=\\"/tutorials/part5-deep-learning-and-llms/overview\\">Part V</a></td>\\n      <td>Deep learning and LLM track: FFNs, CNNs, forecasting, RNNs, Transformers, fine-tuning, and alignment.</td>\\n      <td>Read by cluster: FFN, CNN, sequence models, then LLMs.</td>\\n    </tr>\\n    <tr>\\n      <td><a href=\\"/tutorials/part6-appendices/overview\\">Part VI</a></td>\\n      <td>Supporting references: interview talk track and print-oriented classification source.</td>\\n      <td>Use as review material or a printable companion.</td>\\n    </tr>\\n  </tbody>\\n</table>\\n\\n<h2 id=\\"concept-map\\">Concept Map</h2>\\n<table>\\n  <thead>\\n    <tr>\\n      <th>Concept cluster</th>\\n      <th>Primary chapter</th>\\n      <th>Related chapters and why they revisit it</th>\\n    </tr>\\n  </thead>\\n  <tbody>\\n    <tr>\\n      <td>Enterprise delivery artifacts, roles, gates, and decision flow</td>\\n      <td><a href=\\"/tutorials/part1-enterprise-ai-delivery/05-seven-days-after-kickoff\\">Part I Ch. 5</a> for the post-kickoff document pack; <a href=\\"/tutorials/part1-enterprise-ai-delivery/10-hld-to-lld-sprint-plan\\">Ch. 10</a> for sprint conversion.</td>\\n      <td>Ch. 1-4 introduce the same people and artifacts from intake and kickoff. Ch. 6-11 reuse them during architecture, review, implementation, and provisioning.</td>\\n    </tr>\\n    <tr>\\n      <td>HTTP and FastAPI request handling</td>\\n      <td><a href=\\"/tutorials/part2-backend-platform-security/03-fastapi-request-mapping\\">Part II Ch. 3</a></td>\\n      <td>Ch. 1 introduces FastAPI/Uvicorn and briefly names methods. Ch. 2 owns HTTP verb semantics. Ch. 3 owns the exact mapping from raw HTTP to FastAPI function arguments.</td>\\n    </tr>\\n    <tr>\\n      <td>Pydantic data modeling, dataclass bridge, validation, serialization, settings, aliases, and LLM output contracts</td>\\n      <td><a href=\\"/tutorials/part2-backend-platform-security/04-pydantic-data-models\\">Part II Ch. 4</a></td>\\n      <td>Ch. 3 introduces Pydantic through a FastAPI request body. Ch. 4 gives the full explanation from Python classes/dataclasses through production API, settings, queue, and LLM validation patterns.</td>\\n    </tr>\\n    <tr>\\n      <td>OAuth2, OIDC, PKCE, bearer tokens, JWTs, opaque tokens, and API keys</td>\\n      <td><a href=\\"/tutorials/part2-backend-platform-security/09-authentication-deep-dive\\">Part II Ch. 10</a></td>\\n      <td>Ch. 7 is the beginner primer, Ch. 8 is the FastAPI implementation, Ch. 9 is user bootstrap, and Ch. 11 adds modern sender-constrained and passwordless patterns. MCP auth chapters reference this theory instead of redefining it.</td>\\n    </tr>\\n    <tr>\\n      <td>End-user identity, tenant isolation, IAM, AD/Workspace groups, and workload identity</td>\\n      <td><a href=\\"/tutorials/part2-backend-platform-security/10-enduser-vs-workload-identity\\">Part II Ch. 12</a></td>\\n      <td>Ch. 13 applies the same three-lane model to AD groups and bootstrap policy. Ch. 14 implements it on GCP. Part I Ch. 6-7 mention it only at architecture-decision level.</td>\\n    </tr>\\n    <tr>\\n      <td>MCP mental model, resources, prompts, tools, discovery, remote servers, and auth</td>\\n      <td><a href=\\"/tutorials/part3-agent-protocols/02-mcp-discovery-remote-auth\\">Part III Ch. 2</a></td>\\n      <td>Ch. 1 is the first-principles local database example. Ch. 3 applies MCP to an enterprise Salesforce pattern. Ch. 4 preserves the 2025 foundation and maps it to the current stateless core. A2A 1.0 in Ch. 5 is deliberately separate: inter-agent delegation, not host-to-tool integration.</td>\\n    </tr>\\n    <tr>\\n      <td>Classical ML workflow: features, target, model, loss, optimizer, fit/predict/score</td>\\n      <td><a href=\\"/tutorials/part4-ml-foundations/02-ml-as-geometry\\">Part IV Ch. 2</a></td>\\n      <td>Ch. 3 instantiates the workflow for numeric regression. Ch. 4 instantiates it for classification with logits, sigmoid/softmax, and accuracy. Ch. 5 branches to trees and ensembles for tabular baselines.</td>\\n    </tr>\\n    <tr>\\n      <td>Feed-forward neural networks, neurons, activations, backprop, batching, and debugging</td>\\n      <td><a href=\\"/tutorials/part5-deep-learning-and-llms/01-ffn-concepts\\">Part V Ch. 1</a> and <a href=\\"/tutorials/part5-deep-learning-and-llms/02-ffn-training-debugging\\">Ch. 2</a></td>\\n      <td><a href=\\"/tutorials/part5-deep-learning-and-llms/03-ffn-canonical-merged\\">Ch. 3</a> is the optional single-chapter reference edition. It repeats the same concepts in one article for print/reference use.</td>\\n    </tr>\\n    <tr>\\n      <td>CNN convolution, feature maps, pooling, implementation, dropout, and train/eval behavior</td>\\n      <td><a href=\\"/tutorials/part5-deep-learning-and-llms/04-cnn-convolution\\">Part V Ch. 4</a> through <a href=\\"/tutorials/part5-deep-learning-and-llms/06-cnn-pytorch-implementation\\">Ch. 6</a></td>\\n      <td><a href=\\"/tutorials/part5-deep-learning-and-llms/07-cnn-dropout-train-eval\\">Ch. 7</a> expands the short dropout and train/eval section from Ch. 6 into a full conceptual and coding deep dive.</td>\\n    </tr>\\n    <tr>\\n      <td>Sequence forecasting, autoregressive windows, leakage, recursion, RNNs, and Transformers</td>\\n      <td><a href=\\"/tutorials/part5-deep-learning-and-llms/08-forecasting-sequence-data\\">Part V Ch. 8</a></td>\\n      <td>Ch. 9 implements the autoregressive linear baseline. Ch. 10 replaces a fixed window with recurrent state, builds from vanilla RNN into GRU/LSTM gates, then uses encoder-decoder translation to show tokens, embeddings, padding, teacher forcing, and autoregressive decoding. Ch. 11 builds from that translation model into cross-attention, self-attention, causal masking, and GPT generation.</td>\\n    </tr>\\n    <tr>\\n      <td>LLM adaptation, SFT, PEFT, LoRA/QLoRA, DPO/RLHF, ORPO, KTO, GRPO, RLAIF</td>\\n      <td><a href=\\"/tutorials/part5-deep-learning-and-llms/12-llm-fine-tuning\\">Part V Ch. 12</a> for adaptation; <a href=\\"/tutorials/part5-deep-learning-and-llms/13-modern-llm-alignment-orpo-grpo\\">Ch. 13</a> for alignment comparison.</td>\\n      <td>Ch. 12 introduces SFT/PEFT and first-generation preference methods. Ch. 13 deliberately repeats the DPO/RLHF baseline only to compare newer alignment methods in one decision framework.</td>\\n    </tr>\\n  </tbody>\\n</table>\\n\\n<h2 id=\\"cross-referenced-concept-clusters\\">Cross-Referenced Concept Clusters</h2>\\n<table>\\n  <thead>\\n    <tr>\\n      <th>Related pages</th>\\n      <th>How to read them</th>\\n    </tr>\\n  </thead>\\n  <tbody>\\n    <tr>\\n      <td>Part II Ch. 12 and Ch. 13: tenant identity, IAM, group gating.</td>\\n      <td>Ch. 12 owns the three-lane model. Ch. 13 is the applied policy/bootstrap chapter.</td>\\n    </tr>\\n    <tr>\\n      <td>Part III Ch. 1, Ch. 2, Ch. 3, and Ch. 4: MCP resources/prompts/tools, discovery, remote servers, auth, and enterprise patterns.</td>\\n      <td>Ch. 2 owns the full technical model. Ch. 1 remains the beginner example, Ch. 3 the enterprise pattern, and Ch. 4 the 2025-to-2026 protocol evolution.</td>\\n    </tr>\\n    <tr>\\n      <td>Part V Ch. 1, Ch. 2, and Ch. 3: FFN concepts, training, batching, backprop, and debugging.</td>\\n      <td>Ch. 1-2 are the teaching path. Ch. 3 is an optional single-article reference edition.</td>\\n    </tr>\\n    <tr>\\n      <td>Part V Ch. 6 and Ch. 7: dropout and train/eval behavior in CNN code.</td>\\n      <td>Ch. 6 introduces the implementation requirement. Ch. 7 is the detailed behavior chapter.</td>\\n    </tr>\\n    <tr>\\n      <td>Part V Ch. 12 and Ch. 13: DPO, RLHF, preference data, and alignment objectives.</td>\\n      <td>Ch. 12 introduces adaptation and earlier alignment methods. Ch. 13 owns the modern comparison across ORPO, KTO, GRPO, RLAIF, and PPO-style RLHF.</td>\\n    </tr>\\n    <tr>\\n      <td>Part IV Ch. 3 and Ch. 4: training loops, loss, optimizer, and evaluation.</td>\\n      <td>The shared workflow is intentional. Ch. 3 is regression; Ch. 4 is classification and changes target type, activation, loss, and metric.</td>\\n    </tr>\\n  </tbody>\\n</table>\\n\\n<h2 id=\\"page-by-page-map\\">Page-by-Page Map</h2>\\n\\n<h3 id=\\"part-i-enterprise-ai-delivery-lifecycle\\">Part I - Enterprise AI Delivery Lifecycle</h3>\\n<table>\\n  <thead><tr><th>Chapter</th><th>Role in the book</th></tr></thead>\\n  <tbody>\\n    <tr><td><a href=\\"/tutorials/part1-enterprise-ai-delivery/01-business-pain-to-ai-lead\\">1. From business pain to AI lead</a></td><td>Introduces the enterprise flow, roles, BU context, example pain point, and day-1 lead responsibilities.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part1-enterprise-ai-delivery/02-intake-package\\">2. The intake package</a></td><td>Defines minimum viable intake, expected stakeholders, red flags, and a copy/paste intake expectation template.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part1-enterprise-ai-delivery/03-ai-lead-response\\">3. AI lead response document</a></td><td>Turns the intake into scope, metrics, controls, risks, architecture sketch, evaluation plan, and asks.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part1-enterprise-ai-delivery/04-kickoff-meeting\\">4. Pilot kickoff meeting</a></td><td>Defines meeting purpose, required attendees, agenda, decisions, questions by role, and post-meeting outputs.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part1-enterprise-ai-delivery/05-seven-days-after-kickoff\\">5. Seven days after kickoff</a></td><td>Canonical playbook for the first week, AI lead document pack, ownership split, and release gates.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part1-enterprise-ai-delivery/06-architecture-reference-design\\">6. Architecture reference design</a></td><td>Maps the app architecture: React, FastAPI, OIDC, token validation, tenant enforcement, DB isolation, and async processing.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part1-enterprise-ai-delivery/07-hld-service-selection\\">7. HLD and service selection</a></td><td>Chooses GCP-aligned services, explains alternatives, constraints, critical path, and architecture review framing.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part1-enterprise-ai-delivery/08-after-hld-next-steps\\">8. After HLD</a></td><td>Explains what changes after HLD, next-step sequencing, practical artifacts, and up-managing.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part1-enterprise-ai-delivery/09-architecture-review\\">9. Architecture review</a></td><td>Owns review prep, agenda, expected reviewer questions, approval conditions, and follow-up capture.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part1-enterprise-ai-delivery/10-hld-to-lld-sprint-plan\\">10. HLD to LLD and sprint plan</a></td><td>Converts HLD boxes into epics, vertical slices, stories, acceptance criteria, ownership, and sprint plan.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part1-enterprise-ai-delivery/11-provisioning-services-scale\\">11. Provisioning, services, scale</a></td><td>Owns concrete provisioning tickets, service choices, latency targets, and scaling for thousands of users.</td></tr>\\n  </tbody>\\n</table>\\n\\n<h3 id=\\"part-ii-backend-platform-and-security\\">Part II - Backend, Platform, and Security</h3>\\n<table>\\n  <thead><tr><th>Chapter</th><th>Role in the book</th></tr></thead>\\n  <tbody>\\n    <tr><td><a href=\\"/tutorials/part2-backend-platform-security/01-fastapi-uvicorn-basics\\">1. FastAPI and Uvicorn basics</a></td><td>Introduces the server runtime, why FastAPI/Uvicorn fit, and the first API mental model.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part2-backend-platform-security/02-http-methods\\">2. HTTP methods</a></td><td>Owns HTTP verb semantics, common REST mappings, and PUT vs POST confusion.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part2-backend-platform-security/03-fastapi-request-mapping\\">3. FastAPI request mapping</a></td><td>Shows the exact path from raw HTTP request to FastAPI parameters and return value.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part2-backend-platform-security/04-pydantic-data-models\\">4. Pydantic data models</a></td><td>Canonical Pydantic chapter: Python classes, dataclasses, why Pydantic exists, BaseModel, validation, coercion vs strictness, aliases, serialization, settings, FastAPI, queues, and LLM outputs.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part2-backend-platform-security/04-concurrency-user-isolation\\">5. Concurrency and user isolation</a></td><td>Explains async concurrency vs parallelism, per-request identity, tenant-scoped repositories, connection pools, backpressure, deadlines, and why shared request state breaks isolation.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part2-backend-platform-security/05-background-tasks-and-retries\\">6. Background tasks and retries</a></td><td>Owns background work, retries, idempotency, and async processing patterns for FastAPI systems.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part2-backend-platform-security/06-sso-oauth2-oidc-primer\\">7. SSO / OAuth2 / OIDC primer</a></td><td>Beginner-friendly explanation of SSO, OAuth2, OIDC, and why applications delegate login.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part2-backend-platform-security/07-oidc-oauth2-pkce-fastapi\\">8. OIDC + OAuth2 + PKCE in FastAPI</a></td><td>Implementation flow for Auth Code + PKCE, bearer tokens, token validation, and backend identity.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part2-backend-platform-security/08-registering-new-users\\">9. First login and user provisioning</a></td><td>Owns token-to-application identity mapping, JIT/invite/SCIM policy, atomic bootstrap, tenant membership, reconciliation, and deprovisioning.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part2-backend-platform-security/09-authentication-deep-dive\\">10. Authentication deep dive</a></td><td>Canonical auth chapter for API keys, bearer tokens, JWT vs opaque tokens, introspection, JWKS, PKCE, MCP auth, and SQL auth.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part2-backend-platform-security/15-modern-auth-additions\\">11. Modern auth additions</a></td><td>Extends auth with passkeys/WebAuthn, DPoP, mTLS sender-constrained tokens, and token exchange.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part2-backend-platform-security/10-enduser-vs-workload-identity\\">12. End-user vs workload identity</a></td><td>Canonical three-lane identity model: end-user identity, app authorization/tenancy, and workload identity/IAM.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part2-backend-platform-security/12-tenant-iam-ad-groups\\">13. Tenant isolation, IAM, AD groups</a></td><td>Applies the identity model to tenant isolation, IAM, group gating, and common mistakes.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part2-backend-platform-security/11-gcp-workload-identity\\">14. GCP workload identity</a></td><td>Implements project setup, service accounts, Google identity, storage design, deployment, networking, and governance on GCP.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part2-backend-platform-security/13-external-service-integration\\">15. Cross-cloud service integration</a></td><td>Compares versioned API keys with Entra workload federation, then covers shared clients, timeouts, retries, rate limits, observability, and data governance.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part2-backend-platform-security/14-github-governance\\">16. GitHub governance and CI</a></td><td>Owns rulesets, status checks, workflows, required workflows, scanning, runners, and merge enforcement.</td></tr>\\n  </tbody>\\n</table>\\n\\n<h3 id=\\"part-iii-agent-protocols-and-integration\\">Part III - Agent Protocols and Integration</h3>\\n<table>\\n  <thead><tr><th>Chapter</th><th>Role in the book</th></tr></thead>\\n  <tbody>\\n    <tr><td><a href=\\"/tutorials/part3-agent-protocols/01-mcp-fundamentals\\">1. MCP fundamentals</a></td><td>Beginner local example for MCP tools, resources, prompts, and why a standard interface matters.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part3-agent-protocols/02-mcp-discovery-remote-auth\\">2. MCP discovery, remote, auth</a></td><td>Canonical MCP technical chapter: server/client code, discovery, remote access, auth, token acquisition, validation, and best practices.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part3-agent-protocols/03-mcp-enterprise-pattern\\">3. MCP enterprise pattern</a></td><td>Applies MCP to FastAPI host -&gt; MCP server -&gt; Salesforce with the enterprise auth story.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part3-agent-protocols/04-mcp-2025-update\\">4. MCP protocol evolution</a></td><td>Preserves the 2025 Streamable HTTP, protected-resource auth, elicitation, structured output, and resource-link foundation, then maps it to the <code>2026-07-28</code> stateless request model, discovery, MRTR, subscriptions, extensions, and deprecations.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part3-agent-protocols/05-a2a-protocol\\">5. A2A protocol 1.0</a></td><td>Separates agent-to-agent collaboration from MCP host-to-tool integration and teaches current Agent Cards, bindings, Messages, Tasks, states, Parts, Artifacts, security, and operations.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part3-agent-protocols/06-javascript-typescript-primer\\">6. JavaScript and TypeScript primer</a></td><td>Self-contained language foundation for readers who need JS/TS before LangChain and Flowise.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part3-agent-protocols/07-langchain-langgraph-flowise\\">7. LangChain -&gt; LangGraph -&gt; Flowise</a></td><td>Maps runnable pipelines, stateful graphs, and UI-based flow composition.</td></tr>\\n  </tbody>\\n</table>\\n\\n<h3 id=\\"part-iv-ml-foundations\\">Part IV - ML Foundations</h3>\\n<table>\\n  <thead><tr><th>Chapter</th><th>Role in the book</th></tr></thead>\\n  <tbody>\\n    <tr><td><a href=\\"/tutorials/part4-ml-foundations/01-introduction-pytorch\\">1. PyTorch foundations</a></td><td>Introduces tensors, shape/dtype/device contracts, autograd, <code>nn.Module</code>, optimizers, train/eval behavior, and the complete training loop used in later chapters.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part4-ml-foundations/02-ml-as-geometry\\">2. ML as geometry</a></td><td>Canonical conceptual base: data as points, models as shapes, regression as fitting, classification as separating.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part4-ml-foundations/03-linear-regression\\">3. Linear regression</a></td><td>Owns straight-line model, MSE, SGD, training loop, and numeric prediction.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part4-ml-foundations/04-linear-classification\\">4. Linear classification</a></td><td>Owns logits, sigmoid/logistic regression, classification loss, accuracy, preprocessing, and PyTorch implementation.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part4-ml-foundations/05-trees-bagging-boosting\\">5. Trees, bagging, boosting</a></td><td>Owns decision trees, Gini/information gain, random forests, AdaBoost, Gradient Boosting, and XGBoost.</td></tr>\\n  </tbody>\\n</table>\\n\\n<h3 id=\\"part-v-deep-learning-and-llms\\">Part V - Deep Learning and LLMs</h3>\\n<table>\\n  <thead><tr><th>Chapter</th><th>Role in the book</th></tr></thead>\\n  <tbody>\\n    <tr><td><a href=\\"/tutorials/part5-deep-learning-and-llms/01-ffn-concepts\\">1. FFN concepts</a></td><td>Owns neurons, layers, feed-forward architecture, activation functions, vanishing gradients, softmax, and flattening images.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part5-deep-learning-and-llms/02-ffn-training-debugging\\">2. FFN training and debugging</a></td><td>Owns mini-batches, DataLoader, scalable training loops, logits vs probabilities, GPU handling, confusion matrices, and debugging.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part5-deep-learning-and-llms/03-ffn-canonical-merged\\">3. FFN single-chapter reference</a></td><td>Optional reference edition that presents Ch. 1-2 in one publication-style article.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part5-deep-learning-and-llms/04-cnn-convolution\\">4. CNN convolution</a></td><td>Owns convolution mechanics, output sizes, convolution modes, equations, cross-correlation, and sliding dot-product intuition.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part5-deep-learning-and-llms/05-cnn-architecture\\">5. CNN architecture</a></td><td>Owns channels, filters, feature maps, pooling, parameter sharing, and full CNN architecture.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part5-deep-learning-and-llms/06-cnn-pytorch-implementation\\">6. CNN PyTorch implementation</a></td><td>Owns Conv2d, nn.Module design, Sequential vs custom modules, model skeletons, dropout introduction, and convolution arithmetic.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part5-deep-learning-and-llms/07-cnn-dropout-train-eval\\">7. CNN dropout and train/eval</a></td><td>Deep dive for dropout masks, inverted scaling, train/eval mode, flattening, and common confusions.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part5-deep-learning-and-llms/08-forecasting-sequence-data\\">8. Forecasting and sequence data</a></td><td>Owns sequence representation, forecasting horizon, AR baseline, leakage, recursive forecasting, and the RNN preview.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part5-deep-learning-and-llms/09-autoregressive-linear-model\\">9. Autoregressive linear model</a></td><td>Owns windowed dataset construction, chronological split, AR model in PyTorch, full-batch training, and correct recursive forecasting.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part5-deep-learning-and-llms/10-recurrent-neural-networks\\">10. Recurrent neural networks</a></td><td>Owns Elman RNN equations, sequence use cases such as language modeling, speech recognition, machine translation, forecasting, music generation, video/sensor streams, many-to-one vs many-to-many, tokenization and embeddings for sequence inputs, GRU update/reset gates, LSTM cell state and gates, bidirectional recurrence, encoder-decoder translation, padding/masking, teacher forcing, autoregressive decoding, manual loop, nn.RNN/GRU/LSTM, hidden state, and recurrent weight sharing.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part5-deep-learning-and-llms/11-transformers-and-attention\\">11. Transformers and attention</a></td><td>Owns the RNN-to-attention bridge, cross-attention, self-attention, causal masking, GPT next-token training and generation, scaled dot-product attention, multi-head attention, positional encoding/RoPE, Transformer blocks, encoder/decoder variants, KV cache, and why Transformers won.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part5-deep-learning-and-llms/12-llm-fine-tuning\\">12. LLM fine-tuning</a></td><td>Owns SFT, data formats, Hugging Face/OpenAI fine-tuning, label masking, PEFT, LoRA/QLoRA, evaluation, DPO, and classic RLHF introduction.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part5-deep-learning-and-llms/13-modern-llm-alignment-orpo-grpo\\">13. Modern LLM alignment</a></td><td>Owns the comparison of DPO, ORPO, KTO, GRPO, RLAIF, PPO-style RLHF, and the decision framework for preference alignment.</td></tr>\\n  </tbody>\\n</table>\\n\\n<h3 id=\\"part-vi-appendices\\">Part VI - Appendices</h3>\\n<table>\\n  <thead><tr><th>Appendix</th><th>Role in the book</th></tr></thead>\\n  <tbody>\\n    <tr><td><a href=\\"/tutorials/part6-appendices/01-lead-ds-interview-talk-track\\">A. Lead DS interview talk track</a></td><td>One-hour narrative synthesis of enterprise AI delivery, multi-tenancy, MCP/A2A, and ML/DL depth.</td></tr>\\n    <tr><td><a href=\\"/tutorials/part6-appendices/02-classification-latex-print\\">B. Classification print edition</a></td><td>Print-oriented LaTeX companion for the linear classification chapter.</td></tr>\\n  </tbody>\\n</table>"}'),d={title:"Reading Guide and Concept Map",slug:"/content-map",description:"This page is the book-level map. It explains the main spine of the book, where each concept is introduced, and where the same idea is revisited from an implementation, architecture, enterprise, or reference angle. Rep...",sidebar_label:"Reading guide and concept map",pagination_label:"Reading guide and concept map",hide_title:!0,hide_table_of_contents:!0},l=void 0,c={},p=[];function h(t){return(0,r.jsx)(o.A,{content:s})}function u(t={}){const{wrapper:e}={...(0,i.R)(),...t.components};return e?(0,r.jsx)(e,{...t,children:(0,r.jsx)(h,{...t})}):h()}}}]);